  guard();p=(rel+'/'+name).lstrip('/');s=os.stat(name,dir_fd=fd,follow_symlinks=False)
  need(s.st_dev==os.fstat(sfd).st_dev and s.st_uid==os.geteuid(),'owned source entry')
  row={'relativePath':p,'identity':ident(s),'mode':stat.S_IMODE(s.st_mode),'allocatedBytes':s.st_blocks*512}
  if stat.S_ISDIR(s.st_mode):
   row['kind']='directory';rows[p]=row
   f=os.open(name,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC,dir_fd=fd)
   try:
    need(ident(os.fstat(f))[:-1]==ident(s)[:-1],'source directory FD')
    collect(f,p,depth+1,rows)
   finally:os.close(f)
  elif stat.S_ISREG(s.st_mode):
   need(s.st_nlink==1,'regular source single link');row['kind']='regular';rows[p]=row
  elif stat.S_ISLNK(s.st_mode):
   row['kind']='symlink-metadata-only';row['linkText']=os.readlink(name,dir_fd=fd);rows[p]=row
  else:raise RuntimeError('unexpected source kind')
